import SwiftUI
struct BaselineView: View {
    @EnvironmentObject var model: AppViewModel
    var body: some View { ScrollView { VStack(alignment:.leading,spacing:16) { HStack { VStack(alignment:.leading) { Text("Configuration Baseline").font(.title2.bold()); Text("Non-secret structural snapshot. Drift is never applied automatically.").foregroundStyle(.secondary) }; Spacer(); Button("Set current state as baseline") { Task { await model.setCurrentBaseline() } }.buttonStyle(.borderedProminent).disabled(model.activeServerID == nil) }; if let baseline = model.configurationBaseline { KeyValueRow(key:"Captured",value:baseline.createdAt.formatted()); KeyValueRow(key:"Public listeners",value:baseline.publicListeners.joined(separator:", ")); KeyValueRow(key:"Services",value:String(baseline.services.count)); KeyValueRow(key:"WireGuard peers",value:String(baseline.peerPublicIdentifiers.count)) } else { ContentUnavailableView("No baseline",systemImage:"scope",description:Text("Refresh Security, then capture current state.")) }; Divider(); Text("Detected drift").font(.headline); if model.baselineDrift.isEmpty { Text("No structural drift detected.").foregroundStyle(.secondary) } else { ForEach(model.baselineDrift) { drift in HStack { Text(drift.kind == .added ? "+" : drift.kind == .removed ? "−" : "~").font(.title3.bold()); VStack(alignment:.leading) { Text(drift.category); Text(drift.key).font(.caption).foregroundStyle(.secondary) }; Spacer() } } } }.padding(20) } }
}
